CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, name TEXT NOT NULL, birth_year INTEGER NOT NULL, sex TEXT NOT NULL, diagnosis TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS encounters (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), admitted_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS beds (id TEXT PRIMARY KEY, ward_id TEXT NOT NULL, room TEXT NOT NULL, nurse TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, type TEXT NOT NULL, sensors TEXT NOT NULL, last_seen TEXT, latest_at TEXT, latest TEXT, scenario TEXT NOT NULL DEFAULT 'normal');
    CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), patient_id TEXT NOT NULL REFERENCES patients(id), encounter_id TEXT NOT NULL REFERENCES encounters(id), bed_id TEXT NOT NULL REFERENCES beds(id), started_at TEXT NOT NULL, ended_at TEXT);
    CREATE UNIQUE INDEX IF NOT EXISTS assignment_device_active ON assignments(device_id) WHERE ended_at IS NULL;
    CREATE UNIQUE INDEX IF NOT EXISTS assignment_bed_active ON assignments(bed_id) WHERE ended_at IS NULL;
    CREATE UNIQUE INDEX IF NOT EXISTS assignment_patient_active ON assignments(patient_id) WHERE ended_at IS NULL;
    CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, device_id TEXT NOT NULL, assignment_id TEXT NOT NULL, patient_id TEXT NOT NULL, measured_at TEXT NOT NULL, received_at TEXT NOT NULL, payload TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS messages_patient_time ON messages(patient_id, measured_at);
    CREATE INDEX IF NOT EXISTS messages_assignment_received ON messages(assignment_id, received_at DESC);
    CREATE TABLE IF NOT EXISTS measurements (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id), patient_id TEXT NOT NULL, code TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL, quality TEXT NOT NULL, source TEXT NOT NULL, sensor_id TEXT NOT NULL, measured_at TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS measurements_patient_time ON measurements(patient_id, measured_at, code);
    CREATE INDEX IF NOT EXISTS measurements_message ON measurements(message_id);
    CREATE TABLE IF NOT EXISTS alarms (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL, patient_id TEXT NOT NULL, bed_id TEXT NOT NULL, rule TEXT NOT NULL, severity TEXT NOT NULL, active INTEGER NOT NULL, opened_at TEXT NOT NULL, cleared_at TEXT, evidence TEXT NOT NULL);
    CREATE UNIQUE INDEX IF NOT EXISTS active_alarm ON alarms(assignment_id, rule) WHERE active=1;
    CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, alarm_id TEXT NOT NULL REFERENCES alarms(id), patient_id TEXT NOT NULL, bed_id TEXT NOT NULL, state TEXT NOT NULL, assignee TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, escalated INTEGER NOT NULL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS request_events (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id), actor TEXT NOT NULL, action TEXT NOT NULL, at TEXT NOT NULL, note TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS care_records (id TEXT PRIMARY KEY, request_id TEXT NOT NULL, patient_id TEXT NOT NULL, actor TEXT NOT NULL, at TEXT NOT NULL, note TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY, device_id TEXT NOT NULL, assignment_id TEXT NOT NULL, bed_id TEXT NOT NULL, mode TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, ack_at TEXT, attempts INTEGER NOT NULL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS rule_state (id TEXT PRIMARY KEY, since_at TEXT, recovery_at TEXT);
    CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, value TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS emr_outbox (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL, last_error TEXT, sent_at TEXT);
    CREATE TABLE IF NOT EXISTS emr_records (id TEXT PRIMARY KEY, payload TEXT NOT NULL, received_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, at TEXT NOT NULL, detail TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS commands_device_time ON commands(device_id, created_at);
    CREATE INDEX IF NOT EXISTS requests_alarm ON requests(alarm_id);
